import { z } from 'zod';

const FETCH_PAGE_TIMEOUT_MS = 10_000;
const InputSchema = z.object({ url: z.string().url() });

export async function fetchPage(input: unknown): Promise<string> {
  const { url } = InputSchema.parse(input);
  const response = await fetch(url, { signal: AbortSignal.timeout(FETCH_PAGE_TIMEOUT_MS) });
  return await response.text();
}
